      "// Reload for next 0.5 ms",
      "// Toggle output pin (e.g., RD0)",
      "// RD0 as output",
      "// Timer1: prescale 1, internal clock (Fosc/4), start",
      "TMR1H = 0xF6; // preload for 0.5 ms",
